/**
 * Worker da Solua Imóveis — formulário de candidatura para corretores(as) parceiros(as).
 * Versão "arquivo único" para colar no editor de código do painel da Cloudflare
 * (Workers & Pages → formsvagas → Edit code).
 *
 * Depois de colar e clicar em "Deploy", configure em Settings → Variables and Secrets:
 *  1) D1 database binding → variable name "DB" → banco "solua-candidaturas"
 *  2) Secret de texto → variable name "ADMIN_TOKEN" → uma senha sua escolha
 *     (protege o painel de candidaturas em /admin)
 */

const INDEX_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n  <title>Trabalhe com a Solua Imóveis</title>\n  <meta name=\"description\" content=\"Cadastro de corretores(as) parceiros(as) — Solua Imóveis\" />\n  <meta name=\"theme-color\" content=\"#024ba5\" />\n  <link rel=\"preconnect\" href=\"https://api.fontshare.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"/styles.css\" />\n</head>\n<body>\n  <div id=\"app\">\n\n    <!-- ===================== TELA INICIAL ===================== -->\n    <section class=\"hero\" data-screen=\"landing\">\n      <div class=\"hero__media\">\n        <img class=\"hero__image\" id=\"landing-image\" src=\"/images/placeholder.svg\" alt=\"\" />\n        <div class=\"hero__overlay\"></div>\n      </div>\n      <div class=\"hero__content\">\n        <h1 class=\"hero__title\" id=\"landing-title\">Vagas para corretores (as)</h1>\n        <p class=\"hero__subtitle\" id=\"landing-subtitle\">\n          Leva menos de 5 minutos. Conte um pouco sobre sua experiência e a forma como você atua\n          no mercado imobiliário para darmos início à conversa.\n        </p>\n        <button class=\"btn btn-primary\" id=\"btn-start\" type=\"button\">Iniciar</button>\n      </div>\n    </section>\n\n    <!-- ===================== FORMULÁRIO (multi-etapas) ===================== -->\n    <form id=\"form\" class=\"hidden\" novalidate>\n\n      <!-- honeypot anti-spam -->\n      <div class=\"honeypot\" aria-hidden=\"true\">\n        <label>Não preencha este campo<input type=\"text\" name=\"website\" id=\"website\" tabindex=\"-1\" autocomplete=\"off\" /></label>\n      </div>\n\n      <!-- ETAPA 1 -->\n      <section class=\"step\" data-step=\"1\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">01</span>\n        <h2 class=\"step__title\">Seus dados</h2>\n        <p class=\"step__desc\">Para começarmos, precisamos te conhecer.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"nome\">Nome completo</label>\n          <input type=\"text\" id=\"nome\" name=\"nome\" autocomplete=\"name\" required />\n          <span class=\"field-error\">Informe seu nome completo.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"email\">E-mail</label>\n          <input type=\"email\" id=\"email\" name=\"email\" autocomplete=\"email\" required />\n          <span class=\"field-error\">Informe um e-mail válido.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"whatsapp\">WhatsApp (com DDD)</label>\n          <span class=\"field__hint\">É por aqui que faremos o primeiro contato.</span>\n          <input type=\"tel\" id=\"whatsapp\" name=\"whatsapp\" placeholder=\"(00) 00000-0000\" autocomplete=\"tel\" required />\n          <span class=\"field-error\">Informe um WhatsApp com DDD.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"cidade\">Cidade / Estado</label>\n          <input type=\"text\" id=\"cidade\" name=\"cidade\" placeholder=\"Ex.: Fortaleza / CE\" required />\n          <span class=\"field-error\">Informe cidade e estado.</span>\n        </div>\n      </section>\n\n      <!-- ETAPA 2 -->\n      <section class=\"step hidden\" data-step=\"2\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">02</span>\n        <h2 class=\"step__title\">Dados profissionais</h2>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"creci\">Número do CRECI (opcional)</label>\n          <input type=\"text\" id=\"creci\" name=\"creci\" />\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Tempo de experiência como corretor(a)</label>\n          <div class=\"options\" data-name=\"experiencia\" data-error=\"Selecione uma opção.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-a\" value=\"Menos de 1 ano\" />\n              <label for=\"exp-a\"><span class=\"option__letter\">A</span>Menos de 1 ano</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-b\" value=\"1 a 3 anos\" />\n              <label for=\"exp-b\"><span class=\"option__letter\">B</span>1 a 3 anos</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-c\" value=\"3 a 5 anos\" />\n              <label for=\"exp-c\"><span class=\"option__letter\">C</span>3 a 5 anos</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"experiencia\" id=\"exp-d\" value=\"Mais de 5 anos\" />\n              <label for=\"exp-d\"><span class=\"option__letter\">D</span>Mais de 5 anos</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"experiencia\">Selecione uma opção.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Já atuou diretamente com captação de imóveis?</label>\n          <span class=\"field__hint\">Prospecção de proprietários, visitas de captação, assinatura de autorização de venda.</span>\n          <div class=\"options simnao\" data-name=\"captacaoResposta\" data-error=\"Responda sim ou não.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"captacaoResposta\" id=\"captacao-sim\" value=\"Sim\" />\n              <label for=\"captacao-sim\">Sim</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"captacaoResposta\" id=\"captacao-nao\" value=\"Não\" />\n              <label for=\"captacao-nao\">Não</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"captacaoResposta\">Responda sim ou não.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"captacaoComentario\">Comente sobre</label>\n          <span class=\"field__hint\">Se quiser, dê um pouco mais de contexto sobre sua resposta.</span>\n          <textarea id=\"captacaoComentario\" name=\"captacaoComentario\" rows=\"3\"></textarea>\n        </div>\n      </section>\n\n      <!-- ETAPA 3 -->\n      <section class=\"step hidden\" data-step=\"3\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">03</span>\n        <h2 class=\"step__title\">Mercado de atuação</h2>\n        <p class=\"step__desc\">Onde e com o que você trabalha hoje.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"regioes\">Região(ões) de atuação</label>\n          <span class=\"field__hint\">Cidades, bairros ou eixos onde você já circula e tem rede de contatos.</span>\n          <textarea id=\"regioes\" name=\"regioes\" rows=\"3\" required></textarea>\n          <span class=\"field-error\">Conte um pouco sobre sua região de atuação.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Tipos de imóvel com que mais trabalha</label>\n          <span class=\"field__hint\">Pode marcar mais de uma opção.</span>\n          <div class=\"options\" data-name=\"tiposImovel\" data-error=\"Selecione ao menos uma opção.\" data-multi=\"true\">\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-a\" value=\"Residencial\" />\n              <label for=\"tipo-a\"><span class=\"option__letter\">A</span>Residencial</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-b\" value=\"Comercial\" />\n              <label for=\"tipo-b\"><span class=\"option__letter\">B</span>Comercial</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-c\" value=\"Terrenos\" />\n              <label for=\"tipo-c\"><span class=\"option__letter\">C</span>Terrenos</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"checkbox\" name=\"tiposImovel\" id=\"tipo-d\" value=\"Rural\" />\n              <label for=\"tipo-d\"><span class=\"option__letter\">D</span>Rural</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"tiposImovel\">Selecione ao menos uma opção.</span>\n        </div>\n      </section>\n\n      <!-- ETAPA 4 -->\n      <section class=\"step hidden\" data-step=\"4\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">04</span>\n        <h2 class=\"step__title\">Disponibilidade</h2>\n        <p class=\"step__desc\">Como você pode se dedicar à rotina de trabalho.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Disponibilidade</label>\n          <div class=\"options\" data-name=\"disponibilidade\" data-error=\"Selecione uma opção.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"disponibilidade\" id=\"disp-a\" value=\"Período integral\" />\n              <label for=\"disp-a\"><span class=\"option__letter\">A</span>Período integral</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"disponibilidade\" id=\"disp-b\" value=\"Meio período\" />\n              <label for=\"disp-b\"><span class=\"option__letter\">B</span>Meio período</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"disponibilidade\" id=\"disp-c\" value=\"Freelancer / por demanda\" />\n              <label for=\"disp-c\"><span class=\"option__letter\">C</span>Freelancer / por demanda</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"disponibilidade\">Selecione uma opção.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Possui veículo próprio?</label>\n          <div class=\"options simnao\" data-name=\"veiculo\" data-error=\"Responda sim ou não.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"veiculo\" id=\"veiculo-sim\" value=\"Sim\" />\n              <label for=\"veiculo-sim\">Sim</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"veiculo\" id=\"veiculo-nao\" value=\"Não\" />\n              <label for=\"veiculo-nao\">Não</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"veiculo\">Responda sim ou não.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"portfolio\">Portfólio / redes sociais</label>\n          <span class=\"field__hint\">Opcional. Instagram, LinkedIn ou site onde acompanhamos seu trabalho.</span>\n          <input type=\"text\" id=\"portfolio\" name=\"portfolio\" placeholder=\"@seuinstagram, linkedin.com/in/..., etc.\" />\n        </div>\n      </section>\n\n      <!-- ETAPA 5 -->\n      <section class=\"step hidden\" data-step=\"5\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">05</span>\n        <h2 class=\"step__title\">Expectativas</h2>\n        <p class=\"step__desc\">Para fecharmos, o que você espera dessa parceria.</p>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"remuneracao\">Modelo de remuneração</label>\n          <span class=\"field__hint\">Seja direto: modelo de comissionamento que considera justo e, se houver, fixo pretendido.</span>\n          <textarea id=\"remuneracao\" name=\"remuneracao\" rows=\"3\" required></textarea>\n          <span class=\"field-error\">Conte o que você espera de remuneração.</span>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\" for=\"sobreVoce\">Sobre você</label>\n          <span class=\"field__hint\">O que te move no mercado imobiliário, uma captação da qual você se orgulha, e por que a Solua.</span>\n          <textarea id=\"sobreVoce\" name=\"sobreVoce\" rows=\"4\"></textarea>\n        </div>\n\n        <div class=\"field\">\n          <label class=\"field__label\">Autorização LGPD</label>\n          <span class=\"field__hint\">\n            Autorizo a Solua Imóveis a armazenar e tratar meus dados pessoais informados neste formulário,\n            conforme a Lei Geral de Proteção de Dados (LGPD), exclusivamente para fins de recrutamento e\n            contato sobre esta vaga.\n          </span>\n          <div class=\"options simnao\" data-name=\"lgpd\" data-error=\"É necessário autorizar para enviar a candidatura.\">\n            <div class=\"option\">\n              <input type=\"radio\" name=\"lgpd\" id=\"lgpd-sim\" value=\"Sim\" />\n              <label for=\"lgpd-sim\">Sim</label>\n            </div>\n            <div class=\"option\">\n              <input type=\"radio\" name=\"lgpd\" id=\"lgpd-nao\" value=\"Não\" />\n              <label for=\"lgpd-nao\">Não</label>\n            </div>\n          </div>\n          <span class=\"field-error\" data-for=\"lgpd\">É necessário autorizar para enviar a candidatura.</span>\n        </div>\n\n        <div class=\"submit-error\" id=\"submit-error\"></div>\n      </section>\n\n      <!-- ETAPA EXTRA: perguntas configuráveis pelo /admin. Só aparece se houver alguma. -->\n      <section class=\"step hidden\" data-step=\"6\" id=\"step-extra\">\n        <div class=\"progress\"></div>\n        <span class=\"step__eyebrow\">06</span>\n        <h2 class=\"step__title\">Mais algumas perguntas</h2>\n        <p class=\"step__desc\">Perguntas adicionais definidas pela Solua.</p>\n        <div id=\"step-extra-fields\"></div>\n      </section>\n\n      <div class=\"actions\">\n        <button class=\"btn btn-ghost\" id=\"btn-back\" type=\"button\">Voltar</button>\n        <button class=\"btn btn-primary\" id=\"btn-next\" type=\"button\">Avançar</button>\n      </div>\n    </form>\n\n    <!-- ===================== TELA DE AGRADECIMENTO ===================== -->\n    <section class=\"thanks hidden\" data-screen=\"thanks\">\n      <div class=\"hero__media\">\n        <img class=\"hero__image\" id=\"thanks-image\" src=\"/images/placeholder.svg\" alt=\"\" />\n        <div class=\"hero__overlay\"></div>\n      </div>\n      <div class=\"thanks__content\">\n        <div class=\"thanks__check\">✓</div>\n        <h1 class=\"thanks__title\" id=\"thanks-title\">Recebemos sua candidatura!</h1>\n        <p class=\"thanks__message\" id=\"thanks-message\">\n          Obrigado por dedicar seu tempo. Nosso time vai analisar suas respostas e entrar em\n          contato pelo WhatsApp informado em breve.\n        </p>\n      </div>\n    </section>\n\n  </div>\n\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n";
const STYLES_CSS = "@import url('https://api.fontshare.com/v2/css?f[]=satoshi@400,500,700,900&display=swap');\n\n:root {\n  --azul: #024ba5;\n  --azul-escuro: #012e66;\n  --azul-tint: #e5edf9;\n  --creme: #f2ede6;\n  --creme-escuro: #e2d9c9;\n  --branco: #ffffff;\n  --texto: #0b1b2b;\n  --texto-suave: #5c6773;\n  --erro: #c23b2e;\n  --radius: 14px;\n  font-size: 16px;\n}\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  min-height: 100%;\n}\n\nbody {\n  font-family: \"Satoshi\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  background: var(--creme);\n  color: var(--texto);\n  display: flex;\n  justify-content: center;\n}\n\n#app {\n  width: 100%;\n  max-width: 640px;\n  min-height: 100vh;\n  background: var(--branco);\n  box-shadow: 0 0 40px rgba(2, 75, 165, 0.08);\n  display: flex;\n  flex-direction: column;\n}\n\n/* ---------- Tela de abertura ---------- */\n\n.hero {\n  position: relative;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  color: #fff;\n  background: var(--azul-escuro);\n}\n\n.hero__media {\n  position: absolute;\n  inset: 0;\n  z-index: 0;\n}\n\n.hero__image {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.hero__overlay {\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(180deg, rgba(1,46,102,0.45) 0%, rgba(1,46,102,0.82) 65%, rgba(1,20,46,0.96) 100%);\n}\n\n.hero__content {\n  position: relative;\n  z-index: 2;\n  margin-top: auto;\n  padding: 40px 28px 48px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.hero__title {\n  font-size: 2.1rem;\n  line-height: 1.15;\n  margin: 0;\n  font-weight: 900;\n  letter-spacing: -0.01em;\n}\n\n.hero__title.title-size-small { font-size: 1.6rem; }\n.hero__title.title-size-large { font-size: 2.6rem; }\n\n.hero__subtitle {\n  margin: 0;\n  color: #dfe7f2;\n  font-size: 1rem;\n  line-height: 1.5;\n}\n\n/* ---------- Botões ---------- */\n\n.btn {\n  appearance: none;\n  border: none;\n  border-radius: 999px;\n  padding: 16px 28px;\n  font-size: 1rem;\n  font-weight: 700;\n  cursor: pointer;\n  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;\n  font-family: inherit;\n}\n\n.btn:active { transform: scale(0.98); }\n\n.btn-primary {\n  background: var(--azul);\n  color: #fff;\n  box-shadow: 0 8px 20px rgba(2, 75, 165, 0.35);\n}\n\n.btn-primary:hover { box-shadow: 0 10px 24px rgba(2, 75, 165, 0.45); }\n\n.btn-primary:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n  box-shadow: none;\n}\n\n.btn-ghost {\n  background: transparent;\n  color: var(--texto-suave);\n  padding: 16px 18px;\n}\n\n.hero .btn-primary {\n  width: 100%;\n  background: var(--creme);\n  color: var(--azul-escuro);\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);\n}\n\n.hero .btn-primary:hover { box-shadow: 0 10px 28px rgba(0, 0, 0, 0.3); }\n\n.actions {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  margin-top: -12px;\n  padding: 0 24px 40px;\n}\n\n.actions .btn-primary { flex: 1; }\n\n/* ---------- Etapas do formulário ---------- */\n\n.step {\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n  padding: 28px 24px 40px;\n}\n\n.progress {\n  display: flex;\n  gap: 6px;\n  margin-bottom: 22px;\n}\n\n.progress__bar {\n  flex: 1;\n  height: 4px;\n  border-radius: 2px;\n  background: var(--creme-escuro);\n  overflow: hidden;\n}\n\n.progress__bar.is-filled { background: var(--azul); }\n\n.step__eyebrow {\n  color: var(--azul);\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  font-size: 0.8rem;\n  text-transform: uppercase;\n  margin-bottom: 6px;\n}\n\n.step__title {\n  font-size: 1.5rem;\n  margin: 0 0 6px;\n  color: var(--texto);\n  font-weight: 900;\n}\n\n.step__desc {\n  color: var(--texto-suave);\n  margin: 0 0 24px;\n  line-height: 1.5;\n}\n\n.field {\n  margin-bottom: 22px;\n}\n\n.field label.field__label {\n  display: block;\n  font-weight: 700;\n  margin-bottom: 4px;\n  color: var(--texto);\n}\n\n.field__hint {\n  display: block;\n  color: var(--texto-suave);\n  font-size: 0.85rem;\n  margin-bottom: 8px;\n  line-height: 1.4;\n}\n\n.field input[type=\"text\"],\n.field input[type=\"email\"],\n.field input[type=\"tel\"],\n.field textarea {\n  width: 100%;\n  border: 1.5px solid var(--creme-escuro);\n  border-radius: 10px;\n  padding: 13px 14px;\n  font-size: 1rem;\n  font-family: inherit;\n  color: var(--texto);\n  background: var(--branco);\n  transition: border-color 0.15s ease;\n}\n\n.field input:focus,\n.field textarea:focus {\n  outline: none;\n  border-color: var(--azul);\n}\n\n.field textarea {\n  resize: vertical;\n  min-height: 90px;\n}\n\n.field-error {\n  display: none;\n  color: var(--erro);\n  font-size: 0.85rem;\n  margin-top: 6px;\n}\n\n.field.has-error input,\n.field.has-error textarea {\n  border-color: var(--erro);\n}\n\n.field.has-error .field-error { display: block; }\n\n/* opções (radio / checkbox estilo cartão) */\n\n.options {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.option {\n  position: relative;\n}\n\n.option input {\n  position: absolute;\n  opacity: 0;\n  width: 1px;\n  height: 1px;\n}\n\n.option label {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  border: 1.5px solid var(--creme-escuro);\n  border-radius: 10px;\n  padding: 13px 14px;\n  cursor: pointer;\n  transition: border-color 0.15s ease, background 0.15s ease;\n}\n\n.option__letter {\n  flex: 0 0 auto;\n  width: 26px;\n  height: 26px;\n  border-radius: 50%;\n  border: 1.5px solid var(--creme-escuro);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.8rem;\n  font-weight: 700;\n  color: var(--texto-suave);\n}\n\n.option input:checked + label {\n  border-color: var(--azul);\n  background: var(--azul-tint);\n}\n\n.option input:checked + label .option__letter {\n  background: var(--azul);\n  border-color: var(--azul);\n  color: #fff;\n}\n\n.option input:focus-visible + label {\n  outline: 2px solid var(--azul);\n  outline-offset: 2px;\n}\n\n/* sim / não em linha */\n\n.simnao {\n  display: flex;\n  gap: 10px;\n}\n\n.simnao .option { flex: 1; }\n.simnao .option label { justify-content: center; }\n.simnao .option__letter { display: none; }\n\n/* ---------- Tela de agradecimento ---------- */\n\n.thanks {\n  position: relative;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  color: #fff;\n  background: var(--azul-escuro);\n}\n\n.thanks__media {\n  position: absolute;\n  inset: 0;\n  z-index: 0;\n}\n\n.thanks__content {\n  position: relative;\n  z-index: 2;\n  margin: auto;\n  padding: 40px 28px;\n  text-align: center;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 14px;\n}\n\n.thanks__check {\n  width: 56px;\n  height: 56px;\n  border-radius: 50%;\n  background: var(--creme);\n  color: var(--azul-escuro);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.6rem;\n  margin-bottom: 6px;\n  font-weight: 900;\n}\n\n.thanks__title {\n  font-size: 1.7rem;\n  margin: 0;\n  font-weight: 900;\n}\n\n.thanks__message {\n  margin: 0;\n  color: #dfe7f2;\n  line-height: 1.55;\n  max-width: 46ch;\n}\n\n/* ---------- utilitários ---------- */\n\n.hidden { display: none !important; }\n\n.submit-error {\n  color: var(--erro);\n  background: rgba(194, 59, 46, 0.08);\n  border: 1px solid rgba(194, 59, 46, 0.25);\n  border-radius: 10px;\n  padding: 12px 14px;\n  margin-top: 16px;\n  font-size: 0.9rem;\n  display: none;\n}\n\n.submit-error.is-visible { display: block; }\n\n.spinner {\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  border: 2px solid rgba(255,255,255,0.35);\n  border-top-color: #fff;\n  animation: spin 0.7s linear infinite;\n  display: inline-block;\n  vertical-align: middle;\n  margin-right: 8px;\n}\n\n@keyframes spin { to { transform: rotate(360deg); } }\n\n.honeypot { position: absolute; left: -9999px; top: -9999px; }\n\n/* ---------- Telas maiores (tablet / desktop) ---------- */\n\n@media (min-width: 900px) {\n  body {\n    padding: 48px 24px;\n    align-items: center;\n  }\n\n  #app {\n    max-width: 1000px;\n    min-height: auto;\n    border-radius: 24px;\n    overflow: hidden;\n    box-shadow: 0 30px 80px rgba(2, 75, 165, 0.18);\n  }\n\n  /* tela inicial e agradecimento viram duas colunas: foto + conteúdo */\n  .hero,\n  .thanks {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    min-height: 620px;\n  }\n\n  .hero__media,\n  .thanks__media {\n    position: relative;\n    inset: auto;\n    height: 100%;\n  }\n\n  .hero__overlay {\n    background: none;\n  }\n\n  .hero__content {\n    position: relative;\n    margin-top: 0;\n    height: 100%;\n    justify-content: center;\n    padding: 56px;\n    gap: 20px;\n  }\n\n  .hero__title { font-size: 2.5rem; }\n  .hero__title.title-size-small { font-size: 2rem; }\n  .hero__title.title-size-large { font-size: 3rem; }\n  .hero__subtitle { font-size: 1.05rem; max-width: 40ch; }\n\n  .hero .btn-primary {\n    width: auto;\n    align-self: flex-start;\n    padding: 16px 36px;\n  }\n\n  .thanks__content {\n    height: 100%;\n    margin: 0;\n    padding: 56px;\n    text-align: left;\n    align-items: flex-start;\n  }\n\n  .thanks__message { max-width: 40ch; }\n\n  /* etapas do formulário: card mais largo, conteúdo com leitura confortável */\n  .step {\n    min-height: 560px;\n    max-width: 600px;\n    margin: 0 auto;\n    padding: 56px 0 64px;\n    justify-content: center;\n  }\n\n  .actions {\n    max-width: 600px;\n    margin: -12px auto 0;\n    padding: 0 0 56px;\n  }\n}\n";
const APP_JS = "/**\n * Formulário de candidatura — Solua Imóveis\n *\n * ---------------------------------------------------------------\n * PARA PERSONALIZAR: os textos/foto/perguntas padrão abaixo (CONFIG)\n * só valem enquanto ninguém salvou nada em Configurações no /admin.\n * Depois de salvar por lá, o que estiver no banco manda — este\n * objeto vira só o \"modo de segurança\" caso o banco esteja vazio.\n * ---------------------------------------------------------------\n */\nconst CAPA_URL = \"https://drive.google.com/thumbnail?id=1AQSDOAJ0f0w6NtLSyc3UzGU-DSGaUwpz&sz=w1600\";\n\nconst CONFIG = {\n  capa: {\n    image: CAPA_URL,\n    position: \"center\",\n  },\n  landing: {\n    title: \"Vagas para corretores (as)\",\n    titleSize: \"normal\",\n    subtitle:\n      \"Leva menos de 5 minutos. Conte um pouco sobre sua experiência e a forma como você atua \" +\n      \"no mercado imobiliário para darmos início à conversa.\",\n    buttonLabel: \"Iniciar\",\n  },\n  thanks: {\n    title: \"Recebemos sua candidatura!\",\n    message:\n      \"Obrigado por dedicar seu tempo. Nosso time vai analisar suas respostas e entrar em \" +\n      \"contato pelo WhatsApp informado em breve.\",\n  },\n  extraQuestions: [],\n};\n\nconst BASE_STEPS = 5;\nlet TOTAL_STEPS = BASE_STEPS;\nlet extraQuestions = [];\n\n/** Mescla a configuração salva no banco (se houver) por cima dos padrões locais. */\nfunction mergeConfig(saved) {\n  if (!saved || typeof saved !== \"object\") return CONFIG;\n  return {\n    capa: { ...CONFIG.capa, ...(saved.capa || {}) },\n    landing: { ...CONFIG.landing, ...(saved.landing || {}) },\n    thanks: { ...CONFIG.thanks, ...(saved.thanks || {}) },\n    extraQuestions: Array.isArray(saved.extraQuestions) ? saved.extraQuestions : [],\n  };\n}\n\nasync function loadConfig() {\n  try {\n    const res = await fetch(\"/api/config\");\n    if (!res.ok) return CONFIG;\n    const data = await res.json();\n    return mergeConfig(data.config);\n  } catch {\n    return CONFIG; // offline ou API fora do ar: segue com os padrões locais\n  }\n}\n\nfunction escapeHtml(value) {\n  const div = document.createElement(\"div\");\n  div.textContent = value == null ? \"\" : String(value);\n  return div.innerHTML;\n}\n\nfunction applyConfig(cfg) {\n  document.getElementById(\"landing-image\").src = cfg.capa.image;\n  document.getElementById(\"landing-image\").style.objectPosition = cfg.capa.position || \"center\";\n  document.getElementById(\"landing-title\").textContent = cfg.landing.title;\n  document.getElementById(\"landing-subtitle\").textContent = cfg.landing.subtitle;\n  document.getElementById(\"btn-start\").textContent = cfg.landing.buttonLabel;\n\n  const titleEl = document.getElementById(\"landing-title\");\n  titleEl.classList.remove(\"title-size-small\", \"title-size-large\");\n  if (cfg.landing.titleSize === \"small\") titleEl.classList.add(\"title-size-small\");\n  if (cfg.landing.titleSize === \"large\") titleEl.classList.add(\"title-size-large\");\n\n  document.getElementById(\"thanks-image\").src = cfg.capa.image;\n  document.getElementById(\"thanks-image\").style.objectPosition = cfg.capa.position || \"center\";\n  document.getElementById(\"thanks-title\").textContent = cfg.thanks.title;\n  document.getElementById(\"thanks-message\").textContent = cfg.thanks.message;\n}\n\n/** Monta os campos da etapa extra (perguntas configuráveis) a partir do CONFIG. */\nfunction buildExtraStep(questions) {\n  const stepEl = document.getElementById(\"step-extra\");\n  const fieldsEl = document.getElementById(\"step-extra-fields\");\n  if (!stepEl || !fieldsEl) return;\n\n  if (!questions.length) {\n    stepEl.remove();\n    return;\n  }\n\n  fieldsEl.innerHTML = questions\n    .map((q) => {\n      const name = `extra_${q.id}`;\n      const label = escapeHtml(q.label);\n\n      if (q.type === \"textarea\") {\n        return `<div class=\"field\">\n          <label class=\"field__label\" for=\"${name}\">${label}</label>\n          <textarea id=\"${name}\" name=\"${name}\" rows=\"3\" ${q.required ? \"required\" : \"\"}></textarea>\n          <span class=\"field-error\">Preencha esse campo.</span>\n        </div>`;\n      }\n\n      if (q.type === \"escolha\") {\n        const opts = (q.options || [])\n          .map((opt, oi) => {\n            const letter = String.fromCharCode(65 + oi);\n            return `<div class=\"option\">\n              <input type=\"radio\" name=\"${name}\" id=\"${name}-${oi}\" value=\"${escapeHtml(opt)}\" />\n              <label for=\"${name}-${oi}\"><span class=\"option__letter\">${letter}</span>${escapeHtml(opt)}</label>\n            </div>`;\n          })\n          .join(\"\");\n        return `<div class=\"field\">\n          <label class=\"field__label\">${label}</label>\n          <div class=\"options\" data-name=\"${name}\" data-error=\"Selecione uma opção.\" ${q.required ? \"\" : 'data-optional=\"true\"'}>${opts}</div>\n          <span class=\"field-error\" data-for=\"${name}\">Selecione uma opção.</span>\n        </div>`;\n      }\n\n      return `<div class=\"field\">\n        <label class=\"field__label\" for=\"${name}\">${label}</label>\n        <input type=\"text\" id=\"${name}\" name=\"${name}\" ${q.required ? \"required\" : \"\"} />\n        <span class=\"field-error\">Preencha esse campo.</span>\n      </div>`;\n    })\n    .join(\"\");\n}\n\nfunction buildProgressBars() {\n  document.querySelectorAll(\".progress\").forEach((container) => {\n    const stepEl = container.closest(\".step\");\n    const currentStep = Number(stepEl.dataset.step);\n    container.innerHTML = \"\";\n    for (let i = 1; i <= TOTAL_STEPS; i++) {\n      const bar = document.createElement(\"div\");\n      bar.className = \"progress__bar\" + (i <= currentStep ? \" is-filled\" : \"\");\n      container.appendChild(bar);\n    }\n  });\n}\n\nfunction showScreen(name) {\n  document.querySelectorAll(\"[data-screen]\").forEach((el) => {\n    el.classList.toggle(\"hidden\", el.dataset.screen !== name);\n  });\n  const form = document.getElementById(\"form\");\n  form.classList.toggle(\"hidden\", name !== \"form\");\n  window.scrollTo(0, 0);\n}\n\nlet currentStep = 1;\n\nfunction showStep(n) {\n  currentStep = n;\n  document.querySelectorAll(\".step\").forEach((el) => {\n    el.classList.toggle(\"hidden\", Number(el.dataset.step) !== n);\n  });\n  document.getElementById(\"btn-back\").style.visibility = n === 1 ? \"hidden\" : \"visible\";\n  document.getElementById(\"btn-next\").textContent = n === TOTAL_STEPS ? \"Enviar\" : \"Avançar\";\n  window.scrollTo(0, 0);\n}\n\nfunction setFieldError(fieldEl, hasError) {\n  fieldEl.classList.toggle(\"has-error\", hasError);\n}\n\n/** Valida a etapa atual; retorna true se pode avançar. */\nfunction validateStep(n) {\n  let valid = true;\n  const stepEl = document.querySelector(`.step[data-step=\"${n}\"]`);\n  if (!stepEl) return true;\n\n  // inputs de texto/textarea simples com atributo required\n  stepEl.querySelectorAll(\"input[required], textarea[required]\").forEach((input) => {\n    const fieldEl = input.closest(\".field\");\n    const ok = input.value.trim().length > 0;\n    if (input.type === \"email\" && ok) {\n      const emailOk = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(input.value.trim());\n      setFieldError(fieldEl, !emailOk);\n      if (!emailOk) valid = false;\n      return;\n    }\n    setFieldError(fieldEl, !ok);\n    if (!ok) valid = false;\n  });\n\n  // grupos de opções (radio / checkbox) — obrigatórios, a menos que marcados como opcionais\n  stepEl.querySelectorAll(\".options[data-name]\").forEach((group) => {\n    if (group.dataset.optional === \"true\") return;\n\n    const name = group.dataset.name;\n    const checked = group.querySelectorAll(`input[name=\"${name}\"]:checked`);\n    const errorEl = stepEl.querySelector(`.field-error[data-for=\"${name}\"]`);\n    const ok = checked.length > 0;\n    if (!ok) {\n      valid = false;\n      if (errorEl) errorEl.style.display = \"block\";\n    } else if (errorEl) {\n      errorEl.style.display = \"none\";\n    }\n  });\n\n  return valid;\n}\n\nfunction collectExtraRespostas(fd) {\n  const result = {};\n  extraQuestions.forEach((q) => {\n    const val = fd.get(`extra_${q.id}`);\n    if (val) result[q.label] = val;\n  });\n  return result;\n}\n\nfunction collectFormData() {\n  const form = document.getElementById(\"form\");\n  const fd = new FormData(form);\n\n  return {\n    nome: fd.get(\"nome\") || \"\",\n    email: fd.get(\"email\") || \"\",\n    whatsapp: fd.get(\"whatsapp\") || \"\",\n    cidade: fd.get(\"cidade\") || \"\",\n    creci: fd.get(\"creci\") || \"\",\n    experiencia: fd.get(\"experiencia\") || \"\",\n    captacao: buildCaptacaoText(fd),\n    regioes: fd.get(\"regioes\") || \"\",\n    tiposImovel: fd.getAll(\"tiposImovel\"),\n    disponibilidade: fd.get(\"disponibilidade\") || \"\",\n    veiculo: fd.get(\"veiculo\") || \"\",\n    portfolio: fd.get(\"portfolio\") || \"\",\n    remuneracao: fd.get(\"remuneracao\") || \"\",\n    sobreVoce: fd.get(\"sobreVoce\") || \"\",\n    lgpd: fd.get(\"lgpd\") || \"\",\n    extraRespostas: collectExtraRespostas(fd),\n    website: fd.get(\"website\") || \"\", // honeypot\n  };\n}\n\nfunction buildCaptacaoText(fd) {\n  const resposta = fd.get(\"captacaoResposta\") || \"\";\n  const comentario = (fd.get(\"captacaoComentario\") || \"\").trim();\n  return comentario ? `${resposta} — ${comentario}` : resposta;\n}\n\nasync function submitForm() {\n  const btnNext = document.getElementById(\"btn-next\");\n  const errorBox = document.getElementById(\"submit-error\");\n  errorBox.classList.remove(\"is-visible\");\n  errorBox.textContent = \"\";\n\n  const original = btnNext.innerHTML;\n  btnNext.disabled = true;\n  btnNext.innerHTML = '<span class=\"spinner\"></span>Enviando…';\n\n  try {\n    const res = await fetch(\"/api/submit\", {\n      method: \"POST\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify(collectFormData()),\n    });\n    const data = await res.json().catch(() => ({}));\n\n    if (!res.ok || !data.ok) {\n      throw new Error(data.error || \"Não foi possível enviar sua candidatura. Tente novamente.\");\n    }\n\n    showScreen(\"thanks\");\n  } catch (err) {\n    errorBox.textContent = err.message || \"Erro inesperado. Tente novamente em instantes.\";\n    errorBox.classList.add(\"is-visible\");\n    errorBox.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n  } finally {\n    btnNext.disabled = false;\n    btnNext.innerHTML = original;\n  }\n}\n\nasync function init() {\n  const cfg = await loadConfig();\n\n  extraQuestions = cfg.extraQuestions || [];\n  TOTAL_STEPS = BASE_STEPS + (extraQuestions.length > 0 ? 1 : 0);\n\n  applyConfig(cfg);\n  buildExtraStep(extraQuestions);\n  buildProgressBars();\n  showStep(1);\n\n  document.getElementById(\"btn-start\").addEventListener(\"click\", () => {\n    showScreen(\"form\");\n  });\n\n  document.getElementById(\"btn-back\").addEventListener(\"click\", () => {\n    if (currentStep > 1) showStep(currentStep - 1);\n  });\n\n  document.getElementById(\"btn-next\").addEventListener(\"click\", async () => {\n    if (!validateStep(currentStep)) return;\n\n    if (currentStep < TOTAL_STEPS) {\n      showStep(currentStep + 1);\n    } else {\n      await submitForm();\n    }\n  });\n\n  // Enter não deve enviar o form prematuramente (exceto em textarea, que já quebra linha)\n  document.getElementById(\"form\").addEventListener(\"submit\", (e) => e.preventDefault());\n}\n\ndocument.addEventListener(\"DOMContentLoaded\", init);\n";
const PLACEHOLDER_SVG = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 600\" width=\"800\" height=\"600\">\n  <rect width=\"800\" height=\"600\" fill=\"#024ba5\"/>\n</svg>\n";
const ADMIN_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Painel — Solua Imóveis</title>\n  <meta name=\"theme-color\" content=\"#024ba5\" />\n  <link rel=\"preconnect\" href=\"https://api.fontshare.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"/styles.css\" />\n  <style>\n    body { justify-content: center; align-items: flex-start; padding: 32px 16px; }\n    #admin { width: 100%; max-width: 1200px; background: var(--branco); border-radius: 14px; box-shadow: 0 0 40px rgba(2,75,165,0.08); padding: 28px; }\n    .admin__header { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 20px; }\n    .admin__title { font-size: 1.4rem; font-weight: 900; color: var(--texto); margin: 0; }\n    .admin__gate { max-width: 360px; margin: 60px auto; text-align: center; }\n    .admin__gate input { width: 100%; margin-bottom: 12px; }\n    .admin__count { color: var(--texto-suave); font-size: 0.9rem; }\n\n    .tabs { display: flex; gap: 8px; margin-bottom: 24px; border-bottom: 1.5px solid var(--creme-escuro); }\n    .tab-btn {\n      background: none; border: none; padding: 10px 4px; margin-bottom: -1.5px;\n      font-family: inherit; font-weight: 700; font-size: 0.95rem; color: var(--texto-suave);\n      cursor: pointer; border-bottom: 2.5px solid transparent;\n    }\n    .tab-btn.is-active { color: var(--azul); border-bottom-color: var(--azul); }\n    .tab-panel { display: none; }\n    .tab-panel.is-active { display: block; }\n\n    table { border-collapse: collapse; width: 100%; font-size: 0.85rem; }\n    thead th {\n      text-align: left; background: var(--azul-tint); color: var(--azul-escuro);\n      padding: 10px 12px; position: sticky; top: 0; white-space: nowrap; font-weight: 700;\n    }\n    tbody td { padding: 10px 12px; border-bottom: 1px solid var(--creme-escuro); vertical-align: top; }\n    tbody tr:hover { background: var(--creme); }\n    .table-wrap { overflow-x: auto; border: 1px solid var(--creme-escuro); border-radius: 10px; }\n    .cell-wrap { max-width: 260px; white-space: pre-wrap; }\n    .error-msg { color: var(--erro); margin-top: 10px; font-size: 0.9rem; display: none; }\n    .error-msg.is-visible { display: block; }\n    .success-msg { color: var(--azul); margin-top: 10px; font-size: 0.9rem; display: none; }\n    .success-msg.is-visible { display: block; }\n    .toolbar { display: flex; gap: 10px; }\n    .btn-small { padding: 10px 18px; font-size: 0.9rem; }\n    .btn-delete {\n      background: none; border: 1.5px solid var(--erro); color: var(--erro);\n      border-radius: 8px; padding: 6px 12px; font-size: 0.8rem; font-weight: 700;\n      cursor: pointer; white-space: nowrap;\n    }\n    .btn-delete:hover { background: rgba(194, 59, 46, 0.08); }\n    .btn-delete:disabled { opacity: 0.5; cursor: not-allowed; }\n\n    .settings-section { max-width: 640px; margin-bottom: 32px; }\n    .settings-section h2 { font-size: 1.05rem; font-weight: 900; color: var(--texto); margin: 0 0 4px; }\n    .settings-section .field__hint { margin-bottom: 16px; }\n    .settings-row { display: flex; gap: 16px; }\n    .settings-row .field { flex: 1; }\n    .settings-select {\n      width: 100%; border: 1.5px solid var(--creme-escuro); border-radius: 10px;\n      padding: 13px 14px; font-size: 1rem; font-family: inherit; color: var(--texto); background: var(--branco);\n    }\n\n    .extra-q {\n      border: 1.5px solid var(--creme-escuro); border-radius: 10px; padding: 14px; margin-bottom: 12px;\n    }\n    .extra-q__row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin-bottom: 8px; }\n    .extra-q-label { flex: 1; min-width: 160px; }\n    .extra-q-type { width: auto; min-width: 150px; }\n    .extra-q__required { display: flex; align-items: center; gap: 6px; font-size: 0.85rem; color: var(--texto-suave); white-space: nowrap; }\n    .extra-q-options { width: 100%; margin-top: 4px; min-height: 60px; }\n    .btn-add-question {\n      background: none; border: 1.5px dashed var(--azul); color: var(--azul);\n      border-radius: 10px; padding: 12px; width: 100%; font-weight: 700; cursor: pointer; font-family: inherit;\n    }\n    .btn-add-question:hover { background: var(--azul-tint); }\n  </style>\n</head>\n<body>\n  <div id=\"admin\">\n    <div class=\"admin__gate\" id=\"gate\">\n      <h1 class=\"admin__title\" style=\"margin-bottom: 8px;\">Área restrita</h1>\n      <p class=\"field__hint\" style=\"margin-bottom: 16px;\">Informe o token de administrador para entrar.</p>\n      <input type=\"password\" id=\"token-input\" placeholder=\"Token de administrador\" autofocus />\n      <button class=\"btn btn-primary btn-small\" id=\"btn-enter\" type=\"button\" style=\"width:100%;\">Entrar</button>\n      <p class=\"error-msg\" id=\"gate-error\">Token inválido.</p>\n    </div>\n\n    <div id=\"content\" class=\"hidden\">\n      <div class=\"tabs\">\n        <button class=\"tab-btn is-active\" type=\"button\" data-tab=\"candidaturas\">Candidaturas</button>\n        <button class=\"tab-btn\" type=\"button\" data-tab=\"config\">Configurações</button>\n      </div>\n\n      <!-- ===================== ABA: CANDIDATURAS ===================== -->\n      <div class=\"tab-panel is-active\" id=\"tab-candidaturas\">\n        <div class=\"admin__header\">\n          <h1 class=\"admin__title\">Candidaturas recebidas</h1>\n          <div class=\"toolbar\">\n            <span class=\"admin__count\" id=\"count\"></span>\n            <button class=\"btn btn-ghost btn-small\" id=\"btn-refresh\" type=\"button\">Atualizar</button>\n            <button class=\"btn btn-primary btn-small\" id=\"btn-csv\" type=\"button\">Exportar CSV</button>\n          </div>\n        </div>\n        <div class=\"table-wrap\">\n          <table>\n            <thead>\n              <tr>\n                <th>Data</th>\n                <th>Nome</th>\n                <th>E-mail</th>\n                <th>WhatsApp</th>\n                <th>Cidade/Estado</th>\n                <th>CRECI</th>\n                <th>Experiência</th>\n                <th>Captação</th>\n                <th>Regiões</th>\n                <th>Tipos de imóvel</th>\n                <th>Disponibilidade</th>\n                <th>Veículo</th>\n                <th>Portfólio</th>\n                <th>Remuneração</th>\n                <th>Sobre você</th>\n                <th>LGPD</th>\n                <th>Perguntas extras</th>\n                <th>Ações</th>\n              </tr>\n            </thead>\n            <tbody id=\"rows\"></tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- ===================== ABA: CONFIGURAÇÕES ===================== -->\n      <div class=\"tab-panel\" id=\"tab-config\">\n        <h1 class=\"admin__title\" style=\"margin-bottom: 20px;\">Configurações do site</h1>\n\n        <div class=\"settings-section\">\n          <h2>Capa</h2>\n          <p class=\"field__hint\">Foto usada na tela inicial e na de agradecimento.</p>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-capa-image\">URL da imagem</label>\n            <input type=\"text\" id=\"cfg-capa-image\" placeholder=\"https://...\" />\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-capa-position\">Posição da imagem</label>\n            <select class=\"settings-select\" id=\"cfg-capa-position\">\n              <option value=\"top\">Topo</option>\n              <option value=\"center\">Centro</option>\n              <option value=\"bottom\">Base</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"settings-section\">\n          <h2>Tela inicial</h2>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-title\">Título</label>\n            <input type=\"text\" id=\"cfg-landing-title\" />\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-title-size\">Tamanho do título</label>\n            <select class=\"settings-select\" id=\"cfg-landing-title-size\">\n              <option value=\"small\">Pequeno</option>\n              <option value=\"normal\">Normal</option>\n              <option value=\"large\">Grande</option>\n            </select>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-subtitle\">Subtítulo</label>\n            <textarea id=\"cfg-landing-subtitle\" rows=\"3\"></textarea>\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-landing-button\">Texto do botão</label>\n            <input type=\"text\" id=\"cfg-landing-button\" />\n          </div>\n        </div>\n\n        <div class=\"settings-section\">\n          <h2>Tela de agradecimento</h2>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-thanks-title\">Título</label>\n            <input type=\"text\" id=\"cfg-thanks-title\" />\n          </div>\n          <div class=\"field\">\n            <label class=\"field__label\" for=\"cfg-thanks-message\">Mensagem</label>\n            <textarea id=\"cfg-thanks-message\" rows=\"3\"></textarea>\n          </div>\n        </div>\n\n        <div class=\"settings-section\">\n          <h2>Perguntas extras</h2>\n          <p class=\"field__hint\">Aparecem como uma etapa nova no formulário, depois das perguntas padrão.</p>\n          <div id=\"extra-questions-editor\"></div>\n          <button class=\"btn-add-question\" type=\"button\" id=\"btn-add-question\">+ Adicionar pergunta</button>\n        </div>\n\n        <button class=\"btn btn-primary\" id=\"btn-save-config\" type=\"button\">Salvar configurações</button>\n        <p class=\"error-msg\" id=\"config-error\"></p>\n        <p class=\"success-msg\" id=\"config-success\">Salvo!</p>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    const STORAGE_KEY = \"solua_admin_token\";\n    let currentRows = [];\n    let extraQuestionsDraft = [];\n\n    // Valores padrão exibidos enquanto nada foi salvo em Configurações ainda\n    // (mesmos valores hoje fixos em public/app.js).\n    const DEFAULT_CONFIG = {\n      capa: {\n        image: \"https://drive.google.com/thumbnail?id=1AQSDOAJ0f0w6NtLSyc3UzGU-DSGaUwpz&sz=w1600\",\n        position: \"center\",\n      },\n      landing: {\n        title: \"Vagas para corretores (as)\",\n        titleSize: \"normal\",\n        subtitle:\n          \"Leva menos de 5 minutos. Conte um pouco sobre sua experiência e a forma como você atua \" +\n          \"no mercado imobiliário para darmos início à conversa.\",\n        buttonLabel: \"Iniciar\",\n      },\n      thanks: {\n        title: \"Recebemos sua candidatura!\",\n        message:\n          \"Obrigado por dedicar seu tempo. Nosso time vai analisar suas respostas e entrar em \" +\n          \"contato pelo WhatsApp informado em breve.\",\n      },\n      extraQuestions: [],\n    };\n\n    function fmtDate(iso) {\n      try {\n        return new Date(iso).toLocaleString(\"pt-BR\", { dateStyle: \"short\", timeStyle: \"short\" });\n      } catch {\n        return iso;\n      }\n    }\n\n    function esc(value) {\n      const div = document.createElement(\"div\");\n      div.textContent = value == null ? \"\" : String(value);\n      return div.innerHTML;\n    }\n\n    function fmtExtraRespostas(json) {\n      if (!json) return \"\";\n      try {\n        const obj = JSON.parse(json);\n        return Object.entries(obj)\n          .map(([label, valor]) => `${label}: ${valor}`)\n          .join(\"\\n\");\n      } catch {\n        return \"\";\n      }\n    }\n\n    function renderRows(rows) {\n      currentRows = rows;\n      document.getElementById(\"count\").textContent = rows.length + \" candidatura(s)\";\n      document.getElementById(\"rows\").innerHTML = rows\n        .map(\n          (r) => `<tr>\n            <td>${esc(fmtDate(r.criado_em))}</td>\n            <td>${esc(r.nome)}</td>\n            <td>${esc(r.email)}</td>\n            <td>${esc(r.whatsapp)}</td>\n            <td>${esc(r.cidade)}</td>\n            <td>${esc(r.creci)}</td>\n            <td>${esc(r.experiencia)}</td>\n            <td class=\"cell-wrap\">${esc(r.captacao)}</td>\n            <td class=\"cell-wrap\">${esc(r.regioes)}</td>\n            <td>${esc(r.tipos_imovel)}</td>\n            <td>${esc(r.disponibilidade)}</td>\n            <td>${esc(r.veiculo)}</td>\n            <td class=\"cell-wrap\">${esc(r.portfolio)}</td>\n            <td class=\"cell-wrap\">${esc(r.remuneracao)}</td>\n            <td class=\"cell-wrap\">${esc(r.sobre_voce)}</td>\n            <td>${esc(r.lgpd)}</td>\n            <td class=\"cell-wrap\">${esc(fmtExtraRespostas(r.extra_respostas))}</td>\n            <td><button class=\"btn-delete\" type=\"button\" data-delete-id=\"${esc(r.id)}\">Excluir</button></td>\n          </tr>`\n        )\n        .join(\"\");\n    }\n\n    async function loadData(token) {\n      const res = await fetch(\"/admin/data\", { headers: { \"x-admin-token\": token } });\n      if (!res.ok) {\n        throw new Error(res.status === 401 ? \"Token inválido.\" : \"Erro ao carregar dados.\");\n      }\n      const data = await res.json();\n      return data.rows || [];\n    }\n\n    async function deleteRow(id, btn) {\n      const nome = currentRows.find((r) => String(r.id) === String(id))?.nome || \"essa candidatura\";\n      if (!confirm(`Excluir \"${nome}\"? Essa ação não pode ser desfeita.`)) return;\n\n      const token = sessionStorage.getItem(STORAGE_KEY);\n      btn.disabled = true;\n      btn.textContent = \"Excluindo…\";\n\n      try {\n        const res = await fetch(`/admin/data/${encodeURIComponent(id)}`, {\n          method: \"DELETE\",\n          headers: { \"x-admin-token\": token },\n        });\n        const data = await res.json().catch(() => ({}));\n        if (!res.ok || !data.ok) {\n          throw new Error(data.error || \"Não foi possível excluir.\");\n        }\n        currentRows = currentRows.filter((r) => String(r.id) !== String(id));\n        renderRows(currentRows);\n      } catch (err) {\n        alert(err.message || \"Erro ao excluir.\");\n        btn.disabled = false;\n        btn.textContent = \"Excluir\";\n      }\n    }\n\n    function toCsv(rows) {\n      const headers = [\n        \"criado_em\", \"nome\", \"email\", \"whatsapp\", \"cidade\", \"creci\", \"experiencia\",\n        \"captacao\", \"regioes\", \"tipos_imovel\", \"disponibilidade\", \"veiculo\",\n        \"portfolio\", \"remuneracao\", \"sobre_voce\", \"lgpd\", \"extra_respostas\",\n      ];\n      const escCsv = (v) => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n      const lines = [headers.join(\",\")];\n      rows.forEach((r) => lines.push(headers.map((h) => escCsv(r[h])).join(\",\")));\n      return lines.join(\"\\r\\n\");\n    }\n\n    // ---------------------------------------------------------------\n    // Configurações\n    // ---------------------------------------------------------------\n\n    function renderExtraQuestionsEditor() {\n      const container = document.getElementById(\"extra-questions-editor\");\n      if (!extraQuestionsDraft.length) {\n        container.innerHTML = '<p class=\"field__hint\">Nenhuma pergunta extra ainda.</p>';\n        return;\n      }\n      container.innerHTML = extraQuestionsDraft\n        .map(\n          (q, i) => `\n        <div class=\"extra-q\" data-index=\"${i}\">\n          <div class=\"extra-q__row\">\n            <input type=\"text\" class=\"extra-q-label\" placeholder=\"Pergunta\" value=\"${esc(q.label)}\" />\n            <select class=\"extra-q-type settings-select\">\n              <option value=\"texto\" ${q.type === \"texto\" ? \"selected\" : \"\"}>Texto curto</option>\n              <option value=\"textarea\" ${q.type === \"textarea\" ? \"selected\" : \"\"}>Texto longo</option>\n              <option value=\"escolha\" ${q.type === \"escolha\" ? \"selected\" : \"\"}>Múltipla escolha</option>\n            </select>\n            <label class=\"extra-q__required\">\n              <input type=\"checkbox\" class=\"extra-q-required\" ${q.required ? \"checked\" : \"\"} /> Obrigatória\n            </label>\n            <button type=\"button\" class=\"btn-delete extra-q-remove\">Remover</button>\n          </div>\n          <textarea\n            class=\"extra-q-options\"\n            placeholder=\"Uma opção por linha\"\n            style=\"${q.type === \"escolha\" ? \"\" : \"display:none;\"}\"\n          >${esc((q.options || []).join(\"\\n\"))}</textarea>\n        </div>`\n        )\n        .join(\"\");\n    }\n\n    function addExtraQuestion() {\n      extraQuestionsDraft.push({ label: \"\", type: \"texto\", options: [], required: false });\n      renderExtraQuestionsEditor();\n    }\n\n    function applyConfigToForm(cfg) {\n      document.getElementById(\"cfg-capa-image\").value = cfg.capa.image || \"\";\n      document.getElementById(\"cfg-capa-position\").value = cfg.capa.position || \"center\";\n      document.getElementById(\"cfg-landing-title\").value = cfg.landing.title || \"\";\n      document.getElementById(\"cfg-landing-title-size\").value = cfg.landing.titleSize || \"normal\";\n      document.getElementById(\"cfg-landing-subtitle\").value = cfg.landing.subtitle || \"\";\n      document.getElementById(\"cfg-landing-button\").value = cfg.landing.buttonLabel || \"\";\n      document.getElementById(\"cfg-thanks-title\").value = cfg.thanks.title || \"\";\n      document.getElementById(\"cfg-thanks-message\").value = cfg.thanks.message || \"\";\n      extraQuestionsDraft = (cfg.extraQuestions || []).map((q) => ({ ...q }));\n      renderExtraQuestionsEditor();\n    }\n\n    async function loadConfigIntoForm() {\n      try {\n        const res = await fetch(\"/api/config\");\n        const data = await res.json();\n        applyConfigToForm(data.config || DEFAULT_CONFIG);\n      } catch {\n        applyConfigToForm(DEFAULT_CONFIG);\n      }\n    }\n\n    function collectConfigFromForm() {\n      // garante que a última edição em cada campo de pergunta extra está no draft\n      document.querySelectorAll(\".extra-q\").forEach((el) => {\n        const i = Number(el.dataset.index);\n        extraQuestionsDraft[i].label = el.querySelector(\".extra-q-label\").value;\n        extraQuestionsDraft[i].type = el.querySelector(\".extra-q-type\").value;\n        extraQuestionsDraft[i].required = el.querySelector(\".extra-q-required\").checked;\n        extraQuestionsDraft[i].options = el\n          .querySelector(\".extra-q-options\")\n          .value.split(\"\\n\")\n          .map((s) => s.trim())\n          .filter(Boolean);\n      });\n\n      return {\n        capa: {\n          image: document.getElementById(\"cfg-capa-image\").value.trim(),\n          position: document.getElementById(\"cfg-capa-position\").value,\n        },\n        landing: {\n          title: document.getElementById(\"cfg-landing-title\").value.trim(),\n          titleSize: document.getElementById(\"cfg-landing-title-size\").value,\n          subtitle: document.getElementById(\"cfg-landing-subtitle\").value.trim(),\n          buttonLabel: document.getElementById(\"cfg-landing-button\").value.trim(),\n        },\n        thanks: {\n          title: document.getElementById(\"cfg-thanks-title\").value.trim(),\n          message: document.getElementById(\"cfg-thanks-message\").value.trim(),\n        },\n        extraQuestions: extraQuestionsDraft,\n      };\n    }\n\n    async function saveConfig() {\n      const btn = document.getElementById(\"btn-save-config\");\n      const errorEl = document.getElementById(\"config-error\");\n      const successEl = document.getElementById(\"config-success\");\n      errorEl.classList.remove(\"is-visible\");\n      successEl.classList.remove(\"is-visible\");\n\n      const token = sessionStorage.getItem(STORAGE_KEY);\n      const payload = collectConfigFromForm();\n\n      btn.disabled = true;\n      btn.textContent = \"Salvando…\";\n\n      try {\n        const res = await fetch(\"/admin/config\", {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\", \"x-admin-token\": token },\n          body: JSON.stringify(payload),\n        });\n        const data = await res.json().catch(() => ({}));\n        if (!res.ok || !data.ok) {\n          throw new Error(data.error || \"Não foi possível salvar.\");\n        }\n        applyConfigToForm(data.config);\n        successEl.classList.add(\"is-visible\");\n      } catch (err) {\n        errorEl.textContent = err.message || \"Erro ao salvar.\";\n        errorEl.classList.add(\"is-visible\");\n      } finally {\n        btn.disabled = false;\n        btn.textContent = \"Salvar configurações\";\n      }\n    }\n\n    // ---------------------------------------------------------------\n    // Login / navegação\n    // ---------------------------------------------------------------\n\n    async function tryEnter(token) {\n      const errorEl = document.getElementById(\"gate-error\");\n      errorEl.classList.remove(\"is-visible\");\n      try {\n        const rows = await loadData(token);\n        sessionStorage.setItem(STORAGE_KEY, token);\n        document.getElementById(\"gate\").classList.add(\"hidden\");\n        document.getElementById(\"content\").classList.remove(\"hidden\");\n        renderRows(rows);\n        loadConfigIntoForm();\n      } catch (err) {\n        errorEl.textContent = err.message;\n        errorEl.classList.add(\"is-visible\");\n      }\n    }\n\n    document.getElementById(\"btn-enter\").addEventListener(\"click\", () => {\n      const token = document.getElementById(\"token-input\").value.trim();\n      if (token) tryEnter(token);\n    });\n\n    document.getElementById(\"token-input\").addEventListener(\"keydown\", (e) => {\n      if (e.key === \"Enter\") document.getElementById(\"btn-enter\").click();\n    });\n\n    document.getElementById(\"btn-refresh\").addEventListener(\"click\", async () => {\n      const token = sessionStorage.getItem(STORAGE_KEY);\n      if (token) renderRows(await loadData(token));\n    });\n\n    document.getElementById(\"rows\").addEventListener(\"click\", (e) => {\n      const btn = e.target.closest(\"[data-delete-id]\");\n      if (btn) deleteRow(btn.dataset.deleteId, btn);\n    });\n\n    document.getElementById(\"btn-csv\").addEventListener(\"click\", () => {\n      const blob = new Blob([toCsv(currentRows)], { type: \"text/csv;charset=utf-8;\" });\n      const link = document.createElement(\"a\");\n      link.href = URL.createObjectURL(blob);\n      link.download = \"candidaturas-solua.csv\";\n      link.click();\n    });\n\n    document.querySelectorAll(\".tab-btn\").forEach((btn) => {\n      btn.addEventListener(\"click\", () => {\n        document.querySelectorAll(\".tab-btn\").forEach((b) => b.classList.toggle(\"is-active\", b === btn));\n        document.querySelectorAll(\".tab-panel\").forEach((p) => {\n          p.classList.toggle(\"is-active\", p.id === \"tab-\" + btn.dataset.tab);\n        });\n      });\n    });\n\n    document.getElementById(\"btn-add-question\").addEventListener(\"click\", addExtraQuestion);\n\n    document.getElementById(\"extra-questions-editor\").addEventListener(\"click\", (e) => {\n      const removeBtn = e.target.closest(\".extra-q-remove\");\n      if (!removeBtn) return;\n      const i = Number(removeBtn.closest(\".extra-q\").dataset.index);\n      collectConfigFromForm(); // sincroniza edições pendentes antes de remover\n      extraQuestionsDraft.splice(i, 1);\n      renderExtraQuestionsEditor();\n    });\n\n    document.getElementById(\"extra-questions-editor\").addEventListener(\"change\", (e) => {\n      if (e.target.classList.contains(\"extra-q-type\")) {\n        const optionsEl = e.target.closest(\".extra-q\").querySelector(\".extra-q-options\");\n        optionsEl.style.display = e.target.value === \"escolha\" ? \"\" : \"none\";\n      }\n    });\n\n    document.getElementById(\"btn-save-config\").addEventListener(\"click\", saveConfig);\n\n    // reentra sozinho se já tiver token salvo nesta aba\n    const savedToken = sessionStorage.getItem(STORAGE_KEY);\n    if (savedToken) tryEnter(savedToken);\n  </script>\n</body>\n</html>\n";

const REQUIRED_FIELDS = [
  "nome", "email", "whatsapp", "cidade", "experiencia", "captacao",
  "regioes", "disponibilidade", "remuneracao", "lgpd",
];

function isNonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0;
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}

async function handleSubmit(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ ok: false, error: "JSON inválido." }, 400);
  }

  for (const field of REQUIRED_FIELDS) {
    if (!isNonEmptyString(body[field])) {
      return jsonResponse({ ok: false, error: `Campo obrigatório ausente: ${field}` }, 400);
    }
  }

  if (!Array.isArray(body.tiposImovel) || body.tiposImovel.length === 0) {
    return jsonResponse({ ok: false, error: "Selecione ao menos um tipo de imóvel." }, 400);
  }

  const lgpd = body.lgpd.trim().toLowerCase();
  if (lgpd !== "sim") {
    return jsonResponse(
      { ok: false, error: "É necessário autorizar o tratamento dos dados (LGPD) para enviar a candidatura." },
      400
    );
  }

  if (isNonEmptyString(body.website)) {
    return jsonResponse({ ok: true }); // honeypot: finge sucesso, não grava
  }

  const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim());
  if (!emailOk) {
    return jsonResponse({ ok: false, error: "E-mail inválido." }, 400);
  }

  const now = new Date().toISOString();
  const extraRespostas = body.extraRespostas && typeof body.extraRespostas === "object" ? body.extraRespostas : {};

  if (!env.DB) {
    return jsonResponse(
      { ok: false, error: "Banco de dados não configurado neste Worker (falta o binding DB)." },
      500
    );
  }

  try {
    await env.DB.prepare(
      `INSERT INTO candidaturas
        (nome, email, whatsapp, cidade, creci, experiencia, captacao, regioes,
         tipos_imovel, disponibilidade, veiculo, portfolio, remuneracao, sobre_voce, lgpd, criado_em, extra_respostas)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    )
      .bind(
        body.nome.trim(),
        body.email.trim(),
        body.whatsapp.trim(),
        body.cidade.trim(),
        (body.creci || "").trim() || null,
        body.experiencia.trim(),
        body.captacao.trim(),
        body.regioes.trim(),
        body.tiposImovel.join(", "),
        body.disponibilidade.trim(),
        (body.veiculo || "").trim() || null,
        (body.portfolio || "").trim() || null,
        body.remuneracao.trim(),
        (body.sobreVoce || "").trim() || null,
        "Sim",
        now,
        Object.keys(extraRespostas).length ? JSON.stringify(extraRespostas) : null
      )
      .run();
  } catch (err) {
    return jsonResponse({ ok: false, error: "Erro ao salvar candidatura." }, 500);
  }

  return jsonResponse({ ok: true });
}

function isAuthorizedAdmin(request, env) {
  const token = request.headers.get("x-admin-token") || "";
  return Boolean(env.ADMIN_TOKEN) && token === env.ADMIN_TOKEN;
}

async function handleAdminData(request, env) {
  if (!isAuthorizedAdmin(request, env)) {
    return jsonResponse({ ok: false, error: "Não autorizado." }, 401);
  }

  if (!env.DB) {
    return jsonResponse({ ok: false, error: "Banco de dados não configurado (falta o binding DB)." }, 500);
  }

  const { results } = await env.DB.prepare(
    "SELECT * FROM candidaturas ORDER BY criado_em DESC"
  ).all();

  return jsonResponse({ ok: true, rows: results });
}

/** Exclui uma candidatura pelo id (protegida por token). */
async function handleAdminDelete(request, env, id) {
  if (!isAuthorizedAdmin(request, env)) {
    return jsonResponse({ ok: false, error: "Não autorizado." }, 401);
  }

  if (!env.DB) {
    return jsonResponse({ ok: false, error: "Banco de dados não configurado (falta o binding DB)." }, 500);
  }

  if (!id || !/^\d+$/.test(id)) {
    return jsonResponse({ ok: false, error: "ID inválido." }, 400);
  }

  await env.DB.prepare("DELETE FROM candidaturas WHERE id = ?").bind(id).run();

  return jsonResponse({ ok: true });
}

function str(value, max) {
  return typeof value === "string" ? value.trim().slice(0, max) : "";
}

/** Valida e normaliza a configuração recebida do painel admin antes de salvar. */
function sanitizeConfig(input) {
  const landing = input && input.landing ? input.landing : {};
  const thanks = input && input.thanks ? input.thanks : {};
  const capa = input && input.capa ? input.capa : {};
  const rawQuestions = input && Array.isArray(input.extraQuestions) ? input.extraQuestions : [];

  return {
    capa: {
      image: str(capa.image, 800),
      position: ["top", "center", "bottom"].includes(capa.position) ? capa.position : "center",
    },
    landing: {
      title: str(landing.title, 200),
      titleSize: ["small", "normal", "large"].includes(landing.titleSize) ? landing.titleSize : "normal",
      subtitle: str(landing.subtitle, 600),
      buttonLabel: str(landing.buttonLabel, 60),
    },
    thanks: {
      title: str(thanks.title, 200),
      message: str(thanks.message, 600),
    },
    extraQuestions: rawQuestions
      .slice(0, 20)
      .map((q, i) => ({
        id: "q" + (i + 1),
        label: str(q && q.label, 200),
        type: ["texto", "textarea", "escolha"].includes(q && q.type) ? q.type : "texto",
        options:
          q && q.type === "escolha" && Array.isArray(q.options)
            ? q.options.map((o) => str(o, 100)).filter(Boolean).slice(0, 10)
            : [],
        required: Boolean(q && q.required),
      }))
      .filter((q) => q.label),
  };
}

/** Retorna a configuração salva (ou null se ninguém salvou nada ainda). */
async function handleGetConfig(env) {
  if (!env.DB) return jsonResponse({ ok: true, config: null });
  try {
    const row = await env.DB.prepare("SELECT data FROM site_config WHERE id = 1").first();
    return jsonResponse({ ok: true, config: row ? JSON.parse(row.data) : null });
  } catch {
    return jsonResponse({ ok: true, config: null });
  }
}

/** Salva a configuração (protegido por token). */
async function handleSaveConfig(request, env) {
  if (!isAuthorizedAdmin(request, env)) {
    return jsonResponse({ ok: false, error: "Não autorizado." }, 401);
  }

  if (!env.DB) {
    return jsonResponse({ ok: false, error: "Banco de dados não configurado (falta o binding DB)." }, 500);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ ok: false, error: "JSON inválido." }, 400);
  }

  const config = sanitizeConfig(body);

  await env.DB.prepare(
    "INSERT INTO site_config (id, data) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data"
  )
    .bind(JSON.stringify(config))
    .run();

  return jsonResponse({ ok: true, config });
}

export default {
  async fetch(request, env) {
    try {
      const url = new URL(request.url);

      if (url.pathname === "/api/submit") {
        if (request.method !== "POST") return jsonResponse({ ok: false, error: "Método não permitido." }, 405);
        return await handleSubmit(request, env);
      }

      if (url.pathname === "/api/config") {
        return await handleGetConfig(env);
      }

      if (url.pathname === "/admin/config" && request.method === "POST") {
        return await handleSaveConfig(request, env);
      }

      if (url.pathname.startsWith("/admin/data/") && request.method === "DELETE") {
        const id = url.pathname.slice("/admin/data/".length);
        return await handleAdminDelete(request, env, id);
      }

      if (url.pathname === "/admin/data") {
        return await handleAdminData(request, env);
      }

      if (url.pathname === "/admin") {
        return new Response(ADMIN_HTML, { headers: { "content-type": "text/html; charset=utf-8" } });
      }

      if (url.pathname === "/styles.css") {
        return new Response(STYLES_CSS, { headers: { "content-type": "text/css; charset=utf-8" } });
      }

      if (url.pathname === "/app.js") {
        return new Response(APP_JS, { headers: { "content-type": "text/javascript; charset=utf-8" } });
      }

      if (url.pathname === "/images/placeholder.svg") {
        return new Response(PLACEHOLDER_SVG, { headers: { "content-type": "image/svg+xml; charset=utf-8" } });
      }

      return new Response(INDEX_HTML, { headers: { "content-type": "text/html; charset=utf-8" } });
    } catch (err) {
      // Nunca deixa a página de erro genérica da Cloudflare aparecer sem explicação:
      // mostra a mensagem real pra dar pra diagnosticar na hora.
      const message = (err && err.stack) || String(err);
      return new Response("Erro no Worker:\n\n" + message, {
        status: 500,
        headers: { "content-type": "text/plain; charset=utf-8" },
      });
    }
  },
};
